<script setup>import {reactive} from 'vue';import {router} from '@inertiajs/vue3';import Layout from './Layout.vue';defineProps({boxes:Array});const form=reactive({name:'',size:'',price:'',is_active:true});function create(){router.post('/admin/boxes',form,{onSuccess:()=>Object.assign(form,{name:'',size:'',price:'',is_active:true})})}function toggle(b){router.patch('/admin/boxes/'+b.id,{name:b.name,size:b.size,price:b.price,is_active:!b.is_active},{preserveScroll:true});}</script>
<template><Layout><p class="eyebrow">Catalog</p><h1 class="serif text-5xl font-bold">Boxes</h1><div class="card mt-6"><div class="grid gap-3 sm:grid-cols-3"><input v-model="form.name" class="field" placeholder="Box of 6"><input v-model="form.size" class="field" placeholder="Cookie count"><input v-model="form.price" class="field" placeholder="Price"></div><button @click="create" class="pill dark mt-4">Add box</button></div><div class="mt-5 grid gap-3"><article v-for="b in boxes" :key="b.id" class="card flex items-center justify-between"><div><h2 class="serif text-2xl font-bold">{{b.name}}</h2><p class="text-sm opacity-60">{{b.size}} cookies</p></div><div class="flex items-center gap-3"><b>{{b.price}} EGP</b><button @click="toggle(b)" class="pill">{{b.is_active?'Active':'Hidden'}}</button></div></article></div></Layout></template>
